import logging
from dataclasses import dataclass, field
from types import MappingProxyType
from typing import Mapping
from urllib.parse import urlsplit, urlunsplit

logger = logging.getLogger(__name__)

DEFAULT_BATCH_SIZE = 500
MASK = "***"
SECRET_KEYS = frozenset({"EXPORT_DB_PASSWORD"})
URL_KEYS = frozenset({"EXPORT_DB_URL"})
BOOLEAN_LITERALS = MappingProxyType({"true": True, "false": False})


@dataclass(frozen=True)
class JobConfig:
    db_url: str
    db_password: str = field(repr=False)
    batch_size: int
    dry_run: bool

    @classmethod
    def from_env(cls, env: Mapping[str, str]) -> "JobConfig":
        """Single resolution point: all defaults, validation and logging happen here."""
        logger.info("export job raw config", extra={"raw_config": _redact_raw(env)})
        config = cls(
            db_url=_required(env, "EXPORT_DB_URL"),
            db_password=_required(env, "EXPORT_DB_PASSWORD"),
            batch_size=_positive_int(env.get("EXPORT_BATCH_SIZE", str(DEFAULT_BATCH_SIZE)), "EXPORT_BATCH_SIZE"),
            dry_run=_boolean(env.get("EXPORT_DRY_RUN", "false"), "EXPORT_DRY_RUN"),
        )
        logger.info("export job resolved config", extra={"resolved_config": config.redacted()})
        return config

    def redacted(self) -> Mapping[str, object]:
        return MappingProxyType(
            {
                "db_url": _mask_url_password(self.db_url),
                "db_password": MASK,
                "batch_size": self.batch_size,
                "dry_run": self.dry_run,
            }
        )


def _required(env: Mapping[str, str], key: str) -> str:
    value = env[key]
    if not value.strip():
        raise ValueError(f"{key} must not be empty")
    return value


def _positive_int(raw: str, key: str) -> int:
    value = int(raw)
    if value <= 0:
        raise ValueError(f"{key} must be positive, got {value}")
    return value


def _boolean(raw: str, key: str) -> bool:
    normalized = raw.strip().lower()
    if normalized not in BOOLEAN_LITERALS:
        raise ValueError(f"{key} must be 'true' or 'false', got {raw!r}")
    return BOOLEAN_LITERALS[normalized]


def _mask_url_password(url: str) -> str:
    parts = urlsplit(url)
    if parts.password is None:
        return url
    host = parts.hostname or ""
    port = f":{parts.port}" if parts.port else ""
    return urlunsplit(parts._replace(netloc=f"{parts.username or ''}:{MASK}@{host}{port}"))


def _redact_raw(env: Mapping[str, str]) -> Mapping[str, str]:
    """Raw EXPORT_* input as given, except secrets, which must never reach logs."""
    redacted: dict[str, str] = {}
    for key, value in env.items():
        if not key.startswith("EXPORT_"):
            continue
        if key in SECRET_KEYS:
            redacted[key] = MASK
        elif key in URL_KEYS:
            redacted[key] = _mask_url_password(value)
        else:
            redacted[key] = value
    return MappingProxyType(redacted)

