import dataclasses
import secrets
import unittest

from job_config import JobConfig

DB_SECRET = secrets.token_hex(8)
URL_SECRET = secrets.token_hex(8)
UNRELATED_SECRET = secrets.token_hex(8)
URL = f"postgresql://exporter:{URL_SECRET}@db.internal:5432/sales"
BASE_ENV = {"EXPORT_DB_URL": URL, "EXPORT_DB_PASSWORD": DB_SECRET}


class JobConfigTest(unittest.TestCase):
    def test_defaults_applied(self) -> None:
        config = JobConfig.from_env(BASE_ENV)
        self.assertEqual((config.batch_size, config.dry_run), (500, False))

    def test_overrides_parsed(self) -> None:
        config = JobConfig.from_env({**BASE_ENV, "EXPORT_BATCH_SIZE": "25", "EXPORT_DRY_RUN": "TRUE"})
        self.assertEqual((config.batch_size, config.dry_run), (25, True))

    def test_missing_required_raises(self) -> None:
        for missing in ("EXPORT_DB_URL", "EXPORT_DB_PASSWORD"):
            with self.subTest(missing=missing):
                env = {k: v for k, v in BASE_ENV.items() if k != missing}
                with self.assertRaises(KeyError):
                    JobConfig.from_env(env)

    def test_empty_required_raises(self) -> None:
        with self.assertRaises(ValueError):
            JobConfig.from_env({**BASE_ENV, "EXPORT_DB_PASSWORD": "  "})

    def test_invalid_batch_size_raises(self) -> None:
        for batch in ("0", "-5", "abc", ""):
            with self.subTest(batch=batch), self.assertRaises(ValueError):
                JobConfig.from_env({**BASE_ENV, "EXPORT_BATCH_SIZE": batch})

    def test_invalid_dry_run_raises(self) -> None:
        for flag in ("yes", "1", ""):
            with self.subTest(flag=flag), self.assertRaises(ValueError):
                JobConfig.from_env({**BASE_ENV, "EXPORT_DRY_RUN": flag})

    def test_config_is_frozen(self) -> None:
        config = JobConfig.from_env(BASE_ENV)
        with self.assertRaises(dataclasses.FrozenInstanceError):
            config.batch_size = 1  # type: ignore[misc]

    def test_logs_raw_and_resolved_without_secrets(self) -> None:
        env = {**BASE_ENV, "EXPORT_BATCH_SIZE": "25", "UNRELATED_TOKEN": UNRELATED_SECRET}
        with self.assertLogs("job_config", level="INFO") as captured:
            config = JobConfig.from_env(env)

        raw = next(r for r in captured.records if hasattr(r, "raw_config")).raw_config
        resolved = next(r for r in captured.records if hasattr(r, "resolved_config")).resolved_config
        self.assertEqual(raw["EXPORT_BATCH_SIZE"], "25")
        self.assertNotIn("UNRELATED_TOKEN", raw)
        self.assertEqual((resolved["batch_size"], resolved["dry_run"]), (25, False))
        self.assertIn("exporter:***@db.internal:5432", resolved["db_url"])

        everything = "".join(str(vars(r)) for r in captured.records) + "".join(captured.output) + repr(config)
        for secret in (DB_SECRET, URL_SECRET, UNRELATED_SECRET):
            self.assertNotIn(secret, everything)


if __name__ == "__main__":
    unittest.main()
